export function getBlogPost(slug: string) {
  return blogPosts.find((post) => post.slug === slug)
}

export function getRelatedPosts(post: BlogPost) {
  const sameIndustry = blogPosts.filter((candidate) => candidate.industry === post.industry && candidate.slug !== post.slug)
  const sameProduct = blogPosts.filter((candidate) => candidate.product === post.product && candidate.slug !== post.slug)
  return [...sameIndustry, ...sameProduct].filter((candidate, index, all) => all.findIndex((item) => item.slug === candidate.slug) === index).slice(0, 4)
}

export const blogIndustries: BlogIndustry[] = ['Banking', 'Insurance', 'Government', 'Healthcare', 'Real Estate', 'Logistics']
